def check_prime(n, divisor):
    # Base case: if the divisor exceeds the square root of n, n is prime
    if divisor * divisor > n:
        return True

    # Base case: if the divisor is greater than n, n is not prime
    if divisor > n:
        return False

    # Base case: if the divisor divides n without remainder, n is not prime
    if n % divisor == 0:
        return False

    # Recursive case: check the next divisor
    return check_prime(n, divisor + 1)

